,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'return q''~',
'select OBJECT_NAME,',
'       SUBOBJECT_NAME,',
'       OBJECT_ID,',
'       DATA_OBJECT_ID,',
'       OBJECT_TYPE,',
'       CREATED,',
'       LAST_DDL_TIME,',
